def blocks(*parts):
    return PREFIX + json.dumps(parts, ensure_ascii=False)

def question(title, statement, answer, correction, hint1, hint2, difficulty=1, options=None, method=None, diagram=None):
    return {'title': title, 'statement': statement, 'exercise_type': 'mcq' if options else 'text', 'options': options or [], 'correct_answer': str(answer), 'correction': correction, 'hints': [hint1,hint2], 'steps':[correction], 'method': method or 'Repère les données de cet exercice, applique la propriété correspondante, puis vérifie les unités et le résultat.', 'diagram': diagram, 'difficulty': difficulty, 'points':10}

def exercise_from_math(topic, slot, level):
    # 4 familles de problèmes × 3 jeux de données : 12 exercices par chapitre.
    n = slot % 3
    kind = slot // 3
    diff = 1 if kind == 0 else 2 if kind in (1,2) else 3
    a = [6,9,12][n]; b = [4,7,8][n]; c = [2,3,5][n]
    common = 'Vérifie que le résultat est cohérent avec les valeurs de l’énoncé.'
    q = None
    if topic == 0:  # 6e decimal
        if kind == 0:
            x=f'{a},{c}'; y=f'{a},{b}'; q=(f'Lequel est le plus grand : {x} ou {y} ?', y, f'Les parties entières sont égales à {a}. Compare les dixièmes : {b} > {c}, donc {y} > {x}.', f'Les deux nombres commencent par {a} : compare leurs chiffres après la virgule.', f'Au rang des dixièmes, compare {c} et {b}.', [x,y,'Ils sont égaux'])
        elif kind == 1:
            x=a*10+c; q=(f'Quel est le chiffre des dixièmes de {a},{c}{b} ?', str(c), f'Dans {a},{c}{b}, le premier chiffre après la virgule est {c} : c’est celui des dixièmes.', 'Le chiffre des dixièmes est immédiatement à droite de la virgule.', f'Dans {a},{c}{b}, regarde le {c}, pas le {b}.', [str(c),str(b),str(a)])
        elif kind == 2:
            q=(f'Encadre {a},{c} entre deux entiers consécutifs : quel est le plus petit entier ?', str(a), f'{a} < {a},{c} < {a+1}. Le plus petit entier de l’encadrement est {a}.', f'Compare {a},{c} avec {a} puis avec {a+1}.', 'L’entier inférieur est la partie entière du nombre décimal.', [str(a),str(a+1),str(a-1)])
        else:
            x=f'{a},{b}{c}'; y=f'{a},{b}{c+2}'; q=(f'Entre {x} et {y}, quel nombre est le plus petit ?',x,f'Les dixièmes valent {b} des deux côtés ; au rang des centièmes, {c} < {c+2}, donc {x} < {y}.',f'Les deux nombres commencent par {a},{b} : cherche le premier chiffre différent.', f'Compare ensuite les centièmes {c} et {c+2}.',[x,y,f'{a},{b}{c+1}'])
    elif topic in (1,):
        if kind==0: q=(f'Calcule {a}+{b}.',str(a+b),f'{a}+{b}={a+b}.',f'Pars de {a} et ajoute {b} unités.',f'Vérifie en effectuant {a+b}−{b}.',None)
        elif kind==1: q=(f'Calcule {a*10+b}−{a}.',str(a*9+b),f'{a*10+b}−{a}={a*9+b}.',f'Soustrais {a} du nombre {a*10+b}.','Aligne les unités avant de soustraire.',None)
        elif kind==2: q=(f'Un carnet coûte {a} € et un stylo {b} €. Combien coûtent les deux articles ?',str(a+b),f'{a}+{b}={a+b} €.', 'Il faut réunir les prix des deux articles.', f'Additionne {a} et {b} en conservant l’unité euro.',None)
        else: q=(f'Un élève possède {a*10+b} billes et en donne {a+b}. Combien lui en reste-t-il ?',str(a*9),f'{a*10+b}−({a}+{b})={a*9} billes.', 'Cherche combien de billes sont données au total.', f'Soustrais {a+b} à {a*10+b}.',None)
    elif topic==2:
        if kind==0: q=(f'Calcule {a}×{b}.',str(a*b),f'{a}×{b}={a*b}.',f'Il y a {b} groupes contenant chacun {a} unités.',f'Additionne {a} exactement {b} fois.',None)
        elif kind==1: q=(f'Calcule {a*b}÷{b}.',str(a),f'{a*b}÷{b}={a}, car {a}×{b}={a*b}.', f'Cherche le nombre qui, multiplié par {b}, donne {a*b}.', f'Teste {a}×{b}.',None)
        elif kind==2: q=(f'On range {a*b} livres dans {a} cartons identiques. Combien de livres par carton ?',str(b),f'{a*b}÷{a}={b} livres.',f'Il s’agit de répartir {a*b} livres en {a} parts égales.',f'Quelle multiplication par {a} donne {a*b} ?',None)
        else: q=(f'Une salle compte {a} rangées de {b} sièges. {c} sièges restent inoccupés. Combien de personnes sont assises ?',str(a*b-c),f'{a}×{b}−{c}={a*b-c}.',f'Calcule d’abord le nombre total de sièges : {a} rangées de {b}.',f'Enlève ensuite les {c} sièges vides.',None)
