def sci_exercises(title, level):
    skills=SCI_SKILLS[title]
    ex=[]
    for i,skill in enumerate(skills):
        prompt,ans,w1,w2,correction=skill
        # Hints précis écrits à partir du concept exact de l’item, sans dire la réponse.
        hint1 = SCIENCE_CONCEPT_HINTS[title]
        hint2 = f'La proposition « {w2} » ne correspond pas à la situation donnée. Écarte-la, puis distingue les deux autres en utilisant la propriété étudiée dans « {title} ».'
        ex.append(question(f'Exercice {i+1} — {prompt[:55]}',prompt,ans,correction,hint1,hint2,1 if i<2 else 2 if i<4 else 3,[ans,w1,w2],method=correction))
    for i in range(6):
        template,calc,h1,h2=(SCI_APPS if i<3 else SCI_APPS_ALT)[title]
        a=[6,9,12,15,18,21][i]
        b=[4,5,7,8,9,11][i]
        c=[2,3,4,5,6,7][i]
        st=re.sub(r'\{([^{}]+)\}',lambda match: str(eval(match.group(1), {'__builtins__':{}},{'a':a,'b':b,'c':c})),template)
        result=calc(a,b,c)
        ex.append(question(f'Exercice {i+7} — Application',st,str(result),f'{h1} Résultat : {result}.',h1,re.sub(r'\{([^{}]+)\}',lambda match: str(eval(match.group(1), {'__builtins__':{}},{'a':a,'b':b,'c':c})),h2),1 if i==0 else 2 if i in (1,2) else 3,method=h1))
    return ex

def make_chapter(config, i, subject, level):
    title,summary,p1,t2,p2,t3,p3=config
    lessons=[
        {'title':'Comprendre : '+title,'body':blocks({'type':'paragraph','content':p1},{'type':'note','content':'Objectif : '+summary}),'order_index':1},
        {'title':t2,'body':blocks({'type':'paragraph','content':p2},{'type':'note','content':'À retenir : '+p2}),'order_index':2},
        {'title':t3,'body':blocks({'type':'paragraph','content':p3},{'type':'note','content':'Vérifie que tu as compris : '+p3}),'order_index':3},
    ]
    if subject=='mathematiques':
        theme=i if level=='6e' else i+15
        exercises=[exercise_from_math(theme,k,level) for k in range(12)]
    else: exercises=sci_exercises(title,level)
    for k,ex in enumerate(exercises): ex['order_index']=k+1
    return {'subject':subject,'level':level,'order_index':i+1,'title':title,'summary':summary,'lessons':lessons,'exercises':exercises}

def generate(level):
    subjects=(MATH_6,SCI_6) if level=='6e' else (MATH_5,SCI_5)
    chapters=[make_chapter(cfg,i,slug,level) for slug,arr in zip(('mathematiques','physique-chimie'),subjects) for i,cfg in enumerate(arr)]
    pack={'pack_id':f'fr-{level}-2026-v10','title':f'StudySprint V10 — {level}, mathématiques et sciences, premier catalogue','level':level,'subjects':SUBJECTS,'chapters':chapters}
    assert len(chapters)==25 and sum(len(ch['lessons']) for ch in chapters)==75
    assert sum(len(ch['exercises']) for ch in chapters)==300
    keys=set()
    for ch in chapters:
        for ex in ch['exercises']:
            key=(ch['title'],ex['statement'])
            if key in keys: raise AssertionError(('duplicate',key))
            keys.add(key)
            assert len(ex['hints'])==2 and ex['correct_answer'] and ex['correction']
            if ex['options']:
                assert ex['correct_answer'] in ex['options']
                assert len(set(ex['options']))==len(ex['options']), (ch['title'],ex)
    filename=OUT/f'{level}_2026_v10.json'
    filename.write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(level,'chapters',len(chapters),'lessons',sum(len(ch['lessons']) for ch in chapters),'exercises',sum(len(ch['exercises']) for ch in chapters),'size',filename.stat().st_size)

if __name__=='__main__':
    generate('6e');generate('5e')
